  v_rendimento_liq := COALESCE(v_rendimento, 1) * (1 - COALESCE(v_perda, 0) / 100);
  IF v_rendimento_liq > 0 THEN
    v_custo_unitario := v_custo_total / v_rendimento_liq;
  ELSE
    v_custo_unitario := v_custo_total;
  END IF;

